var ALLOWED_TAGS = ["b", "strong", "i", "em", "u", "s", "br", "p", "div", "blockquote", "span"];
var FONT_CLASSES = ["font-sans", "font-serif", "font-mono"];
var DANGEROUS = [
  "script",
  "style",
  "iframe",
  "object",
  "embed",
  "svg",
  "math",
  "template",
  "noscript",
  "title",
  "textarea",
  "link",
  "meta",
  "base",
  "form",
  "input",
  "button",
  "select",
  "option",
  "applet",
  "frame",
  "frameset",
  "audio",
  "video"
];
function escapeHtml(t) {
  return String(t ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
