function posisiDana(o, peran) {
  const st = String(o?.status || "created");
  const ditahan = Number(o?.qris_final_amount || Number(o?.price || 0) + Number(o?.shipping || 0));
  const fee = 5e3;
  const bersih = Number(o?.price || 0) - fee + Number(o?.shipping || 0);
  if (st === "created") {
    return peran === "pembeli" ? { judul: "Belum ada uang berpindah", isi: "Kamu belum membayar. Pesanan kedaluwarsa sendiri dalam 48 jam.", tone: "abu" } : { judul: "Belum ada uang", isi: "Pembeli belum membayar \u2014 jangan kirim buku dulu.", tone: "abu" };
  }
  if (st === "expired" || st === "cancelled") {
    return { judul: "Tidak ada uang berpindah", isi: "Pesanan batal sebelum dibayar.", tone: "abu" };
  }
  if (st === "paid") {
    return peran === "pembeli" ? { judul: `${rp3(ditahan)} ditahan BERBIRRU`, isi: "Uangmu aman di rekber. Penjual baru menerima setelah buku sampai dan kamu konfirmasi.", tone: "kuning" } : { judul: `${rp3(ditahan)} ditahan rekber`, isi: "Uang sudah masuk tapi BELUM jadi saldomu. Kirim buku, lalu dana cair saat pembeli konfirmasi (otomatis D+5).", tone: "kuning" };
  }
  if (st === "handed") {
    return peran === "pembeli" ? { judul: `${rp3(ditahan)} masih ditahan`, isi: "Buku dalam perjalanan. Tekan \u201CPesanan Diterima\u201D untuk melepas dana ke penjual.", tone: "kuning" } : { judul: `${rp3(ditahan)} masih ditahan`, isi: "Menunggu pembeli konfirmasi. Kalau tidak ada kabar, cair otomatis setelah 5 hari (dan resi harus terverifikasi kurir).", tone: "kuning" };
  }
  if (st === "disputed") {
    return peran === "pembeli" ? { judul: `${rp3(ditahan)} ditahan selama sengketa`, isi: "Owner sedang meninjau. Dana tidak ke mana-mana sampai ada keputusan.", tone: "merah" } : { judul: `${rp3(ditahan)} ditahan selama sengketa`, isi: "Dana belum jadi saldomu. Kalau owner memutuskan untukmu, dana masuk saldo; kalau refund, kembali ke pembeli.", tone: "merah" };
  }
  if (st === "completed") {
    return peran === "pembeli" ? { judul: "Uang sudah diteruskan ke penjual", isi: `${rp3(ditahan)} dilepas dari rekber setelah kamu konfirmasi. Penjual menerima ${rp3(bersih)} (fee rekber ${rp3(fee)} dipotong dari harga).`, tone: "hijau" } : { judul: `Masuk saldo: +${rp3(bersih)}`, isi: `Dari ${rp3(Number(o?.price || 0))} harga buku, fee rekber ${rp3(fee)} dipotong; ongkir ${rp3(Number(o?.shipping || 0))} diteruskan utuh.`, tone: "hijau" };
  }
  if (st === "refunded") {
    return peran === "pembeli" ? { judul: `Saldo kamu +${rp3(Number(o?.refund_amount || ditahan))}`, isi: "Dana sudah masuk Saldo. Bisa dipakai belanja buku lain (asal menutup seluruh tagihan) atau ditarik ke rekening.", tone: "hijau" } : { judul: "Dana kembali ke pembeli", isi: "Uang ini tidak pernah masuk saldomu \u2014 direkber lalu dikembalikan. Tidak ada potongan untukmu.", tone: "abu" };
  }
  return { judul: "Status dana tidak dikenal", isi: `Status pesanan: ${st}`, tone: "abu" };
}
__name(posisiDana, "posisiDana");

